"""PAC ACARS 1.0.6: on block with aircraft whose parking brake can't be read (X-Plane 11 add-ons), a taxi-in hint,
"File anyway" once landed (the PIREP goes to staff review), and a question when the window is closed mid-flight.
Run from the PAC folder (on the server, and on the Windows PC you build PAC ACARS on):   python pac_acars_106.py
Backups: <file>.bak-acars106. Safe to run twice."""
import base64, json, os, re, shutil, sys
ROOT = sys.argv[1] if len(sys.argv) > 1 else "."
D = json.loads(base64.b64decode(""))
bad, done = [], 0
for rel, hunks in D["pairs"].items():
    p = os.path.join(ROOT, rel)
    if not os.path.exists(p):
        bad.append(rel + " (not found)"); continue
    s = open(p, encoding="utf-8", newline="").read(); o = s
    crlf = "\r\n" in s
    if crlf: s = s.replace("\r\n", "\n")
    for old, new in hunks:
        if new in s: continue
        if s.count(old) != 1:
            bad.append(rel + ": " + repr(old.strip()[:70])); continue
        s = s.replace(old, new); done += 1
    if crlf: s = s.replace("\n", "\r\n")
    if s != o:
        if not os.path.exists(p + ".bak-acars106"): shutil.copyfile(p, p + ".bak-acars106")
        open(p, "w", encoding="utf-8", newline="").write(s)
# version 1.0.6 in the build files, whatever they said before
for rel, pats in {"acars_client/build/version_info.txt": [(r"(Version', ')[0-9.]+'", r"\g<1>1.0.6'"), (r"(vers=\()[0-9, ]+(\))", r"\g<1>1, 0, 6, 0\2")],
                  "acars_client/build/installer.iss": [(r'(#define AppVersion ")[0-9.]+"', r'\g<1>1.0.6"')],
                  "acars_client/build/build_acars.bat": [(r'(set "VERSION=)[0-9.]+"', r'\g<1>1.0.6"')]}.items():
    p = os.path.join(ROOT, rel)
    if not os.path.exists(p): continue
    s = open(p, encoding="utf-8", newline="").read(); o = s
    for a, b in pats: s = re.sub(a, b, s)
    if s != o:
        if not os.path.exists(p + ".bak-acars106"): shutil.copyfile(p, p + ".bak-acars106")
        open(p, "w", encoding="utf-8", newline="").write(s); done += 1
c = os.path.join(ROOT, "acars_client", "CHANGELOG.txt")
if os.path.isdir(os.path.dirname(c)):
    old = open(c, encoding="utf-8").read() if os.path.exists(c) else ""
    if "1.0.6" not in old: open(c, "w", encoding="utf-8").write(D["changelog"] + ("\n" + old.split("\n", 3)[-1] if old else "")); done += 1
t = os.path.join(ROOT, "tests", "test_on_block.py")
if os.path.isdir(os.path.dirname(t)): open(t, "w", encoding="utf-8").write(D["test"])
print("PAC ACARS 1.0.6 UPDATE APPLIED (%d changes)" % done if not bad else "PROBLEMS:\n  " + "\n  ".join(bad))
